from fractions import Fraction

def is_squarefree(n):
    if n < 1:
        return False
    d = 2
    while d * d <= n:
        if n % (d*d) == 0:
            return False
        d += 1
    return True

def ipow(b, e):
    r = 1
    for _ in range(e):
        r *= b
    return r

def verify(N, GMAX, AMAX):
    if type(N) is not int or N < 2 or GMAX < 1 or AMAX < 0 or AMAX > 6:
        raise ValueError('FAIL')
    sq = [n for n in range(1, N+1) if is_squarefree(n)]
    gaps = [sq[i+1]-sq[i] for i in range(len(sq)-1)]
    if any(g < 1 or g > GMAX for g in gaps):
        raise ValueError('FAIL')  # gap outside certified range: fail-closed abort
    cnt = {}
    for g in gaps:
        cnt[g] = cnt.get(g, 0) + 1
    # per-gap staircase identity, exact integers
    for g in sorted(cnt):
        for a in range(AMAX+1):
            lhs = sum(ipow(j, a) - ipow(j-1, a) for j in range(1, g+1))
            if lhs != ipow(g, a):
                raise ValueError('FAIL')
    # aggregate identity: sum g^a == sum_j (j^a-(j-1)^a) * C_j, C_j = #{gaps >= j}
    for a in range(AMAX+1):
        total = sum(ipow(g, a) for g in gaps)
        agg = 0
        for j in range(1, GMAX+1):
            Cj = sum(c for g, c in cnt.items() if g >= j)
            agg += (ipow(j, a) - ipow(j-1, a)) * Cj
        if total != agg:
            raise ValueError('FAIL')
    # per-gap exact Fraction means (no floats anywhere)
    for g in sorted(cnt):
        for a in range(AMAX+1):
            m = Fraction(ipow(g, a) * cnt[g], cnt[g])
            if m.denominator != 1:
                raise ValueError('FAIL')
    return True

def run():
    return verify(10000000, 33, 4)

RESULT = run()
